const item = $input.first()?.json || {};
const wf = item.workflow || {};
const exec = item.execution || {};
const err = exec.error || {};

const now = new Date().toLocaleString('pl-PL', { timeZone: 'Europe/Warsaw' });

const msg = `🚨 *NORA MEDIA: Błąd w Automatyzacji n8n!*
━━━━━━━━━━━━━━━━━━━━━━━━
• *Workflow:* ${wf.name || 'Nieznany'}
• *ID:* \`${wf.id || '-'}\`
• *Execution ID:* \`${exec.id || '-'}\`
• *Czas:* ${now}
• *Szczegóły błędu:* \`${(err.message || 'Nieznany błąd wykonania').slice(0, 250)}\`

🔗 [Otwórz egzekucję w n8n](http://localhost:5678/execution/${exec.id || ''})`;

return {
  json: {
    chat_id: '{{TELEGRAM_CHAT_ID}}',
    text: msg,
    parse_mode: 'Markdown',
    disable_web_page_preview: true
  }
};
